import{_ as d,o as a,c as e,ag as r}from"./chunks/framework.i8sMDeRW.js";const p=JSON.parse('{"title":"AI PM 技能图谱","description":"","frontmatter":{},"headers":[],"relativePath":"guide/06-career/ai-pm-skill-map.md","filePath":"guide/06-career/ai-pm-skill-map.md","lastUpdated":1782288443000}'),h={name:"guide/06-career/ai-pm-skill-map.md"};function o(i,t,l,n,s,b){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="ai-pm-技能图谱" tabindex="-1">AI PM 技能图谱 <a class="header-anchor" href="#ai-pm-技能图谱" aria-label="Permalink to &quot;AI PM 技能图谱&quot;">​</a></h1><blockquote><p><strong>2026-05 更新版</strong>：AI PM 的技能图谱不再只是 LLM、Prompt 和数据分析，而是覆盖 <strong>模型能力、RAG、Agent、评估、成本、工具治理、隐私安全、商业化与组织协作</strong> 的综合能力体系。</p></blockquote><hr><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ul><li><a href="#硬技能">硬技能</a></li><li><a href="#产品与业务技能">产品与业务技能</a></li><li><a href="#工具技能">工具技能</a></li><li><a href="#软技能">软技能</a></li><li><a href="#技能成长路线">技能成长路线</a></li></ul><hr><h2 id="硬技能" tabindex="-1">硬技能 <a class="header-anchor" href="#硬技能" aria-label="Permalink to &quot;硬技能&quot;">​</a></h2><h3 id="_1-llm-与模型基础" tabindex="-1">1. LLM 与模型基础 <a class="header-anchor" href="#_1-llm-与模型基础" aria-label="Permalink to &quot;1. LLM 与模型基础&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>技能点</th><th>掌握标准</th></tr></thead><tbody><tr><td>L1 了解</td><td>Token、上下文窗口、系统提示词</td><td>能解释上下文为什么影响成本和质量</td></tr><tr><td>L1 了解</td><td>Transformer 与自回归生成</td><td>能用产品语言解释模型如何生成回答</td></tr><tr><td>L1 了解</td><td>多模态模型</td><td>知道文本、图像、语音、视频输入输出的基本差异</td></tr><tr><td>L2 掌握</td><td>模型能力分层</td><td>能区分 mini、标准、高级推理、多模态、私有模型的适用场景</td></tr><tr><td>L2 掌握</td><td>模型选型</td><td>能按质量、延迟、成本、上下文、工具调用、合规做对比</td></tr><tr><td>L3 精通</td><td>模型路由</td><td>能设计按任务、套餐、风险、成本动态选择模型的策略</td></tr><tr><td>L3 精通</td><td>推理优化</td><td>理解缓存、批处理、KV Cache、量化、speculative decoding 的产品影响</td></tr></tbody></table><h3 id="_2-prompt-与-context-engineering" tabindex="-1">2. Prompt 与 Context Engineering <a class="header-anchor" href="#_2-prompt-与-context-engineering" aria-label="Permalink to &quot;2. Prompt 与 Context Engineering&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>技能点</th><th>掌握标准</th></tr></thead><tbody><tr><td>L1 了解</td><td>基础 Prompt 编写</td><td>能写清晰指令、输出格式和简单示例</td></tr><tr><td>L1 了解</td><td>System Prompt</td><td>知道系统提示词对行为边界的影响</td></tr><tr><td>L2 掌握</td><td>Few-shot / 结构化输出</td><td>能设计稳定输出格式和 schema</td></tr><tr><td>L2 掌握</td><td>Context 组装</td><td>能决定历史、RAG、工具 schema、用户偏好如何进入上下文</td></tr><tr><td>L2 掌握</td><td>Prompt 版本管理</td><td>能记录变更、效果和回滚方案</td></tr><tr><td>L3 精通</td><td>Prompt Pipeline</td><td>能设计多步骤、多分支、可评估的 Prompt 流水线</td></tr><tr><td>L3 精通</td><td>Prompt 注入防御</td><td>能识别直接/间接 Prompt 注入并设计缓解策略</td></tr></tbody></table><h3 id="_3-rag-与知识系统" tabindex="-1">3. RAG 与知识系统 <a class="header-anchor" href="#_3-rag-与知识系统" aria-label="Permalink to &quot;3. RAG 与知识系统&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>技能点</th><th>掌握标准</th></tr></thead><tbody><tr><td>L1 了解</td><td>Embedding 与向量检索</td><td>能解释 RAG 为什么能降低幻觉</td></tr><tr><td>L1 了解</td><td>Chunking</td><td>知道分块大小和语义边界会影响召回</td></tr><tr><td>L2 掌握</td><td>Hybrid Search</td><td>能设计向量 + BM25 + metadata 过滤</td></tr><tr><td>L2 掌握</td><td>Rerank</td><td>知道何时需要重排序提升精度</td></tr><tr><td>L2 掌握</td><td>权限过滤</td><td>知道检索前权限过滤的重要性</td></tr><tr><td>L3 精通</td><td>GraphRAG / 多跳检索</td><td>能为复杂知识关系设计检索策略</td></tr><tr><td>L3 精通</td><td>RAG 评估</td><td>能评估检索召回、引用正确性、答案忠实度</td></tr></tbody></table><h3 id="_4-agent-与工具治理" tabindex="-1">4. Agent 与工具治理 <a class="header-anchor" href="#_4-agent-与工具治理" aria-label="Permalink to &quot;4. Agent 与工具治理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>技能点</th><th>掌握标准</th></tr></thead><tbody><tr><td>L1 了解</td><td>Agent loop</td><td>理解 plan-act-observe 的基本循环</td></tr><tr><td>L1 了解</td><td>Tool calling</td><td>知道工具 schema、参数和返回值会影响模型行为</td></tr><tr><td>L2 掌握</td><td>Agent 工作流</td><td>能设计单 Agent / 多 Agent / 人工审批流程</td></tr><tr><td>L2 掌握</td><td>MCP / 连接器</td><td>理解工具连接标准化带来的机会和风险</td></tr><tr><td>L2 掌握</td><td>工具权限</td><td>能按只读、写入、高风险、不可逆动作分级</td></tr><tr><td>L3 精通</td><td>Agent Runtime</td><td>能设计 run、step、budget、trace、retry、rollback</td></tr><tr><td>L3 精通</td><td>Agent 安全</td><td>能设计沙箱、审批、工具白名单、供应链风险控制</td></tr></tbody></table><h3 id="_5-评估体系" tabindex="-1">5. 评估体系 <a class="header-anchor" href="#_5-评估体系" aria-label="Permalink to &quot;5. 评估体系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>技能点</th><th>掌握标准</th></tr></thead><tbody><tr><td>L1 了解</td><td>人工评估</td><td>能设计基础评分表和标注规范</td></tr><tr><td>L1 了解</td><td>基础指标</td><td>理解准确率、召回率、满意度、任务完成率</td></tr><tr><td>L2 掌握</td><td>Golden Dataset</td><td>能构建覆盖主场景和边界情况的评估集</td></tr><tr><td>L2 掌握</td><td>LLM-as-Judge</td><td>能设计评估 Prompt 并理解其局限</td></tr><tr><td>L2 掌握</td><td>RAG 评估</td><td>能区分检索质量和生成质量</td></tr><tr><td>L3 精通</td><td>持续评估 Pipeline</td><td>能把评估接入 CI/CD 和模型灰度</td></tr><tr><td>L3 精通</td><td>线上失败回流</td><td>能把线上失败样例转为回归集</td></tr></tbody></table><h3 id="_6-成本与商业化基础" tabindex="-1">6. 成本与商业化基础 <a class="header-anchor" href="#_6-成本与商业化基础" aria-label="Permalink to &quot;6. 成本与商业化基础&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>技能点</th><th>掌握标准</th></tr></thead><tbody><tr><td>L1 了解</td><td>Token 成本</td><td>知道输入、输出、缓存、工具都会产生成本</td></tr><tr><td>L2 掌握</td><td>单任务成本测算</td><td>能估算一次会话、一次 RAG、一次 Agent run 成本</td></tr><tr><td>L2 掌握</td><td>免费层限额</td><td>能设计消息、credits、premium requests、Agent runs 限额</td></tr><tr><td>L3 精通</td><td>单位经济学</td><td>能计算毛利率、P95 用户成本、重度用户风险</td></tr><tr><td>L3 精通</td><td>企业定价</td><td>能设计席位 + 用量 + 治理能力 + 专属容量的定价结构</td></tr></tbody></table><h3 id="_7-隐私、安全与合规" tabindex="-1">7. 隐私、安全与合规 <a class="header-anchor" href="#_7-隐私、安全与合规" aria-label="Permalink to &quot;7. 隐私、安全与合规&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>技能点</th><th>掌握标准</th></tr></thead><tbody><tr><td>L1 了解</td><td>AI 隐私风险</td><td>知道用户输入、文件、记忆、trace 都可能含敏感数据</td></tr><tr><td>L1 了解</td><td>内容安全</td><td>知道自残、违法、仇恨、色情、危险行为等风险类型</td></tr><tr><td>L2 掌握</td><td>数据流图</td><td>能梳理输入、模型、RAG、工具、日志、记忆的数据流</td></tr><tr><td>L2 掌握</td><td>用户控制</td><td>能设计导出、删除、关闭训练、关闭记忆等功能</td></tr><tr><td>L2 掌握</td><td>Prompt 注入</td><td>能识别直接和间接注入风险</td></tr><tr><td>L3 精通</td><td>AI 治理清单</td><td>能制定上线门禁、审计、事故响应和回滚流程</td></tr><tr><td>L3 精通</td><td>高风险场景</td><td>能与法务评估医疗、金融、法律、雇佣、未成年人等场景</td></tr></tbody></table><hr><h2 id="产品与业务技能" tabindex="-1">产品与业务技能 <a class="header-anchor" href="#产品与业务技能" aria-label="Permalink to &quot;产品与业务技能&quot;">​</a></h2><h3 id="_1-场景判断" tabindex="-1">1. 场景判断 <a class="header-anchor" href="#_1-场景判断" aria-label="Permalink to &quot;1. 场景判断&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技能点</th><th>说明</th></tr></thead><tbody><tr><td>AI 适用性判断</td><td>判断问题是否真的需要 AI，而不是规则、搜索或流程引擎即可</td></tr><tr><td>用户工作流拆解</td><td>找到 AI 应该介入的位置和人工保留的位置</td></tr><tr><td>风险分级</td><td>判断场景是低风险信息辅助，还是高风险自动化决策</td></tr><tr><td>成功指标定义</td><td>用任务完成率、节省时间、质量提升、成本下降衡量价值</td></tr></tbody></table><h3 id="_2-产品设计" tabindex="-1">2. 产品设计 <a class="header-anchor" href="#_2-产品设计" aria-label="Permalink to &quot;2. 产品设计&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技能点</th><th>说明</th></tr></thead><tbody><tr><td>不确定性 UX</td><td>设计置信度、来源引用、免责声明和反馈入口</td></tr><tr><td>Human-in-the-loop</td><td>在关键步骤加入人工确认、审批和复核</td></tr><tr><td>错误体验</td><td>处理拒答、超时、降级、工具失败和无结果</td></tr><tr><td>透明度</td><td>告诉用户 AI 做了什么、用了什么来源、调用了什么工具</td></tr></tbody></table><h3 id="_3-商业化" tabindex="-1">3. 商业化 <a class="header-anchor" href="#_3-商业化" aria-label="Permalink to &quot;3. 商业化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技能点</th><th>说明</th></tr></thead><tbody><tr><td>订阅设计</td><td>Free / Plus / Pro / Team / Enterprise 分层</td></tr><tr><td>用量设计</td><td>credits、runs、premium requests、GPU time 等抽象</td></tr><tr><td>企业价值</td><td>SSO、审计、数据驻留、专属容量、SLA、DPA</td></tr><tr><td>成本治理</td><td>预算、告警、限流、熔断、模型降级</td></tr></tbody></table><hr><h2 id="工具技能" tabindex="-1">工具技能 <a class="header-anchor" href="#工具技能" aria-label="Permalink to &quot;工具技能&quot;">​</a></h2><h3 id="_1-ai-产品原型与开发工具" tabindex="-1">1. AI 产品原型与开发工具 <a class="header-anchor" href="#_1-ai-产品原型与开发工具" aria-label="Permalink to &quot;1. AI 产品原型与开发工具&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>代表工具</th><th>掌握目标</th></tr></thead><tbody><tr><td>通用 AI 助手</td><td>ChatGPT、Claude、Gemini</td><td>日常研究、写作、分析和原型</td></tr><tr><td>AI 编码</td><td>Cursor、GitHub Copilot、Claude Code、Codex 类工具</td><td>快速验证、代码阅读、PR 辅助</td></tr><tr><td>原型工具</td><td>Figma、Framer、v0、Lovable、Bolt、Replit</td><td>快速生成可交互 Demo</td></tr><tr><td>低代码 AI 平台</td><td>Dify、Coze、Flowise、Langflow</td><td>快速搭建 RAG / Agent 原型</td></tr></tbody></table><h3 id="_2-rag-agent-工程工具" tabindex="-1">2. RAG / Agent 工程工具 <a class="header-anchor" href="#_2-rag-agent-工程工具" aria-label="Permalink to &quot;2. RAG / Agent 工程工具&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>代表工具</th><th>掌握目标</th></tr></thead><tbody><tr><td>编排框架</td><td>LangChain、LangGraph、LlamaIndex、CrewAI</td><td>理解 RAG / Agent 工作流</td></tr><tr><td>连接器 / 协议</td><td>MCP、OpenAPI、Webhook、A2A 相关生态</td><td>理解工具接入和权限风险</td></tr><tr><td>向量数据库</td><td>Milvus、Qdrant、Weaviate、Pinecone、Chroma</td><td>理解检索架构和成本</td></tr><tr><td>搜索 / Rerank</td><td>BM25、Elastic、reranker、hybrid search</td><td>设计更可靠的检索系统</td></tr><tr><td>沙箱</td><td>Docker、Firecracker、gVisor、浏览器沙箱</td><td>理解代码执行和工具调用隔离</td></tr></tbody></table><h3 id="_3-评估与可观测性" tabindex="-1">3. 评估与可观测性 <a class="header-anchor" href="#_3-评估与可观测性" aria-label="Permalink to &quot;3. 评估与可观测性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>代表工具</th><th>掌握目标</th></tr></thead><tbody><tr><td>Prompt / Trace</td><td>LangSmith、Helicone、Portkey、Arize Phoenix</td><td>跟踪调用、成本和失败样例</td></tr><tr><td>RAG 评估</td><td>RAGAS、TruLens、DeepEval</td><td>评估检索和生成质量</td></tr><tr><td>实验追踪</td><td>Weights &amp; Biases、MLflow</td><td>记录模型和 Prompt 实验</td></tr><tr><td>业务分析</td><td>Metabase、Tableau、Looker、Amplitude</td><td>追踪产品指标和转化</td></tr><tr><td>安全测试</td><td>OWASP LLM Top 10、红队样例库、自建 evals</td><td>验证注入、越权和内容安全</td></tr></tbody></table><h3 id="_4-pm-基础工具" tabindex="-1">4. PM 基础工具 <a class="header-anchor" href="#_4-pm-基础工具" aria-label="Permalink to &quot;4. PM 基础工具&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>工具</th><th>掌握目标</th></tr></thead><tbody><tr><td>文档</td><td>Notion、飞书、Confluence、Markdown</td><td>PRD、评估报告、复盘</td></tr><tr><td>项目管理</td><td>Jira、Linear、飞书项目、GitHub Projects</td><td>需求、里程碑、缺陷追踪</td></tr><tr><td>数据</td><td>SQL、Python/Pandas、Excel</td><td>基础分析和成本测算</td></tr><tr><td>协作</td><td>GitHub、Slack、飞书、Zoom</td><td>跨团队推进</td></tr></tbody></table><hr><h2 id="软技能" tabindex="-1">软技能 <a class="header-anchor" href="#软技能" aria-label="Permalink to &quot;软技能&quot;">​</a></h2><h3 id="_1-技术沟通" tabindex="-1">1. 技术沟通 <a class="header-anchor" href="#_1-技术沟通" aria-label="Permalink to &quot;1. 技术沟通&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技能点</th><th>说明</th></tr></thead><tbody><tr><td>与 MLE 沟通</td><td>能把业务目标转成评估数据、失败样例和质量标准</td></tr><tr><td>与工程沟通</td><td>能描述接口、工具权限、日志、回滚和监控需求</td></tr><tr><td>与安全法务沟通</td><td>能解释数据流、风险场景、用户控制和合规需求</td></tr><tr><td>与业务沟通</td><td>能把模型能力、成本和风险翻译成业务收益与约束</td></tr></tbody></table><h3 id="_2-决策能力" tabindex="-1">2. 决策能力 <a class="header-anchor" href="#_2-决策能力" aria-label="Permalink to &quot;2. 决策能力&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技能点</th><th>说明</th></tr></thead><tbody><tr><td>Trade-off</td><td>在质量、成本、延迟、安全、体验之间做取舍</td></tr><tr><td>风险意识</td><td>对高影响错误保持敏感，知道哪些场景不能全自动</td></tr><tr><td>数据驱动</td><td>不凭感觉判断模型好坏，而用评估和线上指标判断</td></tr><tr><td>长期主义</td><td>避免被短期模型能力变化带偏，沉淀可复用系统</td></tr></tbody></table><h3 id="_3-组织影响力" tabindex="-1">3. 组织影响力 <a class="header-anchor" href="#_3-组织影响力" aria-label="Permalink to &quot;3. 组织影响力&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技能点</th><th>说明</th></tr></thead><tbody><tr><td>推动流程</td><td>建立模型升级、评估、灰度和事故响应流程</td></tr><tr><td>方法论沉淀</td><td>把项目经验整理成模板、清单和 playbook</td></tr><tr><td>客户沟通</td><td>能面向企业客户解释安全、合规、ROI 和部署方案</td></tr><tr><td>行业学习</td><td>持续跟踪模型、工具、法规和商业化趋势</td></tr></tbody></table><hr><h2 id="技能成长路线" tabindex="-1">技能成长路线 <a class="header-anchor" href="#技能成长路线" aria-label="Permalink to &quot;技能成长路线&quot;">​</a></h2><h3 id="l1-入门" tabindex="-1">L1 入门 <a class="header-anchor" href="#l1-入门" aria-label="Permalink to &quot;L1 入门&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LLM 基础 + Prompt + PRD + 评估样例 + AI 工具熟练使用</span></span></code></pre></div><p>建议目标：能协助完成一个 AI 功能的需求、Prompt、评估和上线支持。</p><h3 id="l2-独立" tabindex="-1">L2 独立 <a class="header-anchor" href="#l2-独立" aria-label="Permalink to &quot;L2 独立&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RAG / Agent 基础 + 模型选型 + 评估集 + 灰度 + 成本测算</span></span></code></pre></div><p>建议目标：能独立负责一个 AI 模块从 0 到 1。</p><h3 id="l3-资深" tabindex="-1">L3 资深 <a class="header-anchor" href="#l3-资深" aria-label="Permalink to &quot;L3 资深&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>模型路由 + Agent Runtime + 评估平台 + 成本治理 + 安全合规</span></span></code></pre></div><p>建议目标：能负责一条 AI 产品线或 AI 平台能力。</p><h3 id="l4-专家" tabindex="-1">L4 专家 <a class="header-anchor" href="#l4-专家" aria-label="Permalink to &quot;L4 专家&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AI 产品战略 + 商业化体系 + 组织治理 + 行业影响力</span></span></code></pre></div><p>建议目标：能定义公司级 AI 战略并建立可持续产品体系。</p><hr><blockquote><p><strong>结语</strong>：AI PM 的技能不是“懂一点 AI 技术”即可，而是要把模型、数据、工具、体验、成本、安全和商业化整合成一个可持续的产品系统。</p></blockquote>',63)])])}const u=d(h,[["render",o]]);export{p as __pageData,u as default};
